<template>
  <div class="operations-desk">
    <section class="ops-banner"><div><span class="eyebrow">THE ROOM, IN RHYTHM</span><h2>Keep the next battle moving.</h2><p>Plan the day. Look after the floor. Give your stream a running order.</p></div><div class="ops-pulse"><b>{{ active.length }}</b><span>ON STATION</span><b>{{ openIssues }}</b><span>OPEN ISSUES</span></div></section>
    <div class="ops-tabs" aria-label="Operations views"><button v-for="t in tabs" :key="t.id" :class="{active:tab===t.id}" @click="tab=t.id">{{ t.label }}</button></div>
    <template v-if="tab==='schedule'">
      <div class="ops-columns"><section class="org-card"><div class="section-title"><h2>Run of show</h2><button class="btn small" @click="printSheet">Print / save PDF</button></div><p class="muted">All times: {{ zone }}. Blocks are a schedule, not separate bracket pools.</p><div v-if="!sessions.length" class="ops-empty"><span>01</span><h3>Give the day a shape.</h3><p>Add doors, check-in, bracket play and finals. Reserve stations to catch overlaps across events.</p></div><article v-for="s in sessions" :key="s.id" class="session-row" :class="s.status"><div class="session-time">{{ time(s.start) }}<small>{{ date(s.start) }}</small></div><div><span class="status-pill">{{ s.status }}</span><h3>{{ s.title }}</h3><p>{{ s.minutes }} min · {{ s.stations.join(', ') || 'No stations reserved' }}<br>{{ s.owner || 'No owner assigned' }}</p><div class="button-row"><button v-if="s.status!=='done'" class="btn small" :disabled="busy" @click="send('sessionStatus',{id:s.id,status:s.status==='planned'?'live':'done'})">{{ s.status==='planned'?'Start block':'Complete block' }}</button><button v-if="s.status==='planned'" class="org-link-button" :disabled="busy" @click="send('sessionRemove',{id:s.id})">Remove</button></div></div></article></section>
      <form class="org-card ops-form" @submit.prevent="addSession"><span class="eyebrow">PLAN THE NEXT BLOCK</span><label>Block name<input :disabled="busy" v-model="session.title" required maxlength="100" placeholder="Top 8 on the main stage" /></label><label>Start · {{ zone }}<input :disabled="busy" type="datetime-local" v-model="session.start" required /></label><div class="field-pair"><label>Duration (minutes)<input :disabled="busy" type="number" v-model.number="session.minutes" min="5" max="1440" required /></label><label>Lead / pool captain<input :disabled="busy" v-model="session.owner" maxlength="60" placeholder="Name or role" /></label></div><fieldset><legend>Reserve stations</legend><label v-for="s in event.stations" :key="s" class="ops-check"><input :disabled="busy" type="checkbox" v-model="session.stations" :value="s"/>{{ s }}</label></fieldset><button class="btn primary" :disabled="busy">Add schedule block</button><p class="muted">Times are saved with their timezone. Reservations flag schedule overlaps; match calls remain manual.</p></form></div>
    </template>
    <template v-if="tab==='floor'">
      <div class="section-title"><h2>Station control</h2><span>Shared across all events in this workspace</span></div><div class="station-grid"><article v-for="s in event.stations" :key="s" class="station-tile" :class="{occupied:playing(s),offline:offline(s)}"><header><span class="station-icon"><i aria-hidden="true" class="mdi mdi-monitor"></i></span><span class="status-pill">{{ offline(s)?'MAINTENANCE':playing(s)?'IN USE':'AVAILABLE' }}</span></header><h2>{{ s }}</h2><template v-if="playing(s)"><h3>{{ pair(playing(s).match,playing(s).event) }}</h3><p>{{ playing(s).event.name }} · {{ playing(s).match.id }}</p><button v-if="playing(s).event.id===event.id" class="btn small" @click="$emit('match',playing(s).match)">Open match →</button></template><template v-else><p>{{ offline(s)?'Match assignments are blocked.':'Ready for the next set.' }}</p><button class="btn small" :disabled="busy" @click="send('stationAvailability',{station:s,unavailable:!offline(s)})">{{ offline(s)?'Reopen station':'Take offline' }}</button></template></article></div>
      <section class="org-card"><div class="section-title"><h2>Player call clock</h2><span>Operator decides all forfeits</span></div><p>Use your published no-show policy. The timer survives refresh; it never awards a loss automatically.</p><form class="ops-inline" @submit.prevent="send('callStart',{matchId:callMatch,minutes:callMinutes})"><label>Match<select aria-label="Match" :disabled="busy" v-model="callMatch" required><option value="">Choose a match</option><option v-for="m in available" :key="m.id" :value="m.id">{{ m.id }} · {{ pair(m,event) }}</option></select></label><label>Call window (minutes)<input :disabled="busy" type="number" v-model.number="callMinutes" min="1" max="30" required /></label><button class="btn primary" :disabled="busy || !callMatch">Start / restart call</button></form><div v-for="m in calls" :key="m.id" class="call-row"><div><b>{{ pair(m,event) }}</b><small>{{ m.id }} · deadline {{ time(ops.calls[m.id]) }}</small></div><strong :class="{expired:remaining(ops.calls[m.id])==='Time elapsed'}">{{ remaining(ops.calls[m.id]) }}</strong><button class="btn small" @click="$emit('match',m)">Review match</button><button class="org-link-button" :disabled="busy" @click="send('callClear',{matchId:m.id})">Clear call</button></div></section>
    </template>
    <template v-if="tab==='rundown'">
      <div class="ops-columns"><section class="org-card"><div class="section-title"><h2>Up next on stream</h2><span>{{ rundown.length }} planned sets</span></div><p>Build a running order, then open each set to send it to OBS. This list does not hold a match or block station calls.</p><div v-if="!rundown.length" class="ops-empty"><span>↗</span><h3>Tell a better tournament story.</h3><p>Line up the sets your audience should see.</p></div><article v-for="(m,i) in rundown" :key="m.id" class="rundown-row"><b class="rundown-number">{{ String(i+1).padStart(2,'0') }}</b><div><h3>{{ pair(m,event) }}</h3><p>{{ m.id }} · {{ m.label }} · FT{{ m.ft }}</p><div class="button-row"><button class="btn small" @click="$emit('match',m)">Open controls</button><button class="org-link-button" :disabled="busy || i===0" @click="send('rundownUp',{matchId:m.id})">Move up</button><button class="org-link-button" :disabled="busy" @click="send('rundownRemove',{matchId:m.id})">Remove</button></div></div></article></section><section class="org-card"><h2>Available sets</h2><p>Ready or playing matches from this event.</p><div v-for="m in available.filter(m=>!ops.rundown.includes(m.id))" :key="m.id" class="ops-pick"><div><b>{{ pair(m,event) }}</b><small>{{ m.id }} · {{ m.section }}</small></div><button class="btn small" :disabled="busy" :aria-label="'Queue '+m.id+' for stream'" @click="send('rundownAdd',{matchId:m.id})">+ Queue</button></div></section></div>
    </template>
    <template v-if="tab==='issues'">
      <div class="ops-columns"><section class="org-card"><div class="section-title"><h2>Notes & incidents</h2><span>{{ openIssues }} open</span></div><p>Keep rulings, controller faults and handover notes with the event backup.</p><div v-if="!ops.issues.length" class="ops-empty"><span>✓</span><h3>A clear desk.</h3><p>Record issues here as they come up.</p></div><article v-for="i in ops.issues" :key="i.id" class="issue-row" :class="{resolved:i.resolved}"><span class="status-pill">{{ i.resolved?'Resolved':'Open' }}</span><h3>{{ i.title }}</h3><p>{{ i.owner || 'Unassigned' }} · {{ i.matchId || 'General' }} · {{ date(i.at) }} {{ time(i.at) }}</p><button class="org-link-button" :disabled="busy" @click="send('issueResolve',{id:i.id,resolved:!i.resolved})">{{ i.resolved?'Reopen':'Mark resolved' }}</button></article></section><form class="org-card ops-form" @submit.prevent="addIssue"><h2>Record an issue</h2><label>What needs attention?<textarea :disabled="busy" v-model="issue.title" required maxlength="500" rows="4" placeholder="Station 4 controller disconnect; pause and check cable." /></label><label>Assigned to<input :disabled="busy" v-model="issue.owner" maxlength="60" placeholder="Organizer / referee" /></label><label>Related match<select :disabled="busy" v-model="issue.matchId"><option value="">General event note</option><option v-for="m in event.matches" :key="m.id" :value="m.id">{{ m.id }} · {{ m.label }}</option></select></label><button class="btn primary" :disabled="busy">Save issue</button></form></div>
    </template>
    <div class="print-sheet"><h1>{{ event.name }}</h1><p>Run of show · {{ zone }}</p><table><thead><tr><th>Start</th><th>Block</th><th>Duration</th><th>Stations</th><th>Lead</th></tr></thead><tbody><tr v-for="s in sessions" :key="s.id"><td>{{ date(s.start) }} {{ time(s.start) }}</td><td>{{ s.title }}</td><td>{{ s.minutes }} min</td><td>{{ s.stations.join(', ') }}</td><td>{{ s.owner }}</td></tr></tbody></table></div>
  </div>
</template>
<script lang="ts">
import {Vue,Component,Prop} from 'vue-property-decorator'
import {Event as TournamentEvent,Organizer,Match} from 'src/extension/organizer/engine'
import {emptyOperations} from 'src/extension/organizer/operations'
@Component
export default class OperationsDesk extends Vue {
  @Prop({required:true}) event!:TournamentEvent
  @Prop({required:true}) state!:Organizer
  @Prop({required:true}) command!:(action:string,data:any)=>Promise<any>
  @Prop({default:false}) busy!:boolean
  tab='schedule';tabs=[{id:'schedule',label:'Run of show'},{id:'floor',label:'Stations & calls'},{id:'rundown',label:'Stream plan'},{id:'issues',label:'Notes & incidents'}]
  session={title:'',start:'',minutes:60,owner:'',stations:[] as string[]};issue={title:'',owner:'',matchId:''};callMatch='';callMinutes=5;now=Date.now();timer:any=null
  get zone(){return Intl.DateTimeFormat().resolvedOptions().timeZone}
  get ops(){return this.event.operations||emptyOperations()}
  get sessions(){return this.ops.sessions.slice().sort((a,b)=>a.start.localeCompare(b.start))}
  get available(){return this.event.matches.filter(m=>['ready','playing'].includes(m.status))}
  get active(){return this.event.matches.filter(m=>m.status==='playing')}
  get calls(){return this.available.filter(m=>this.ops.calls[m.id])}
  get rundown(){return this.ops.rundown.map(id=>this.available.find(m=>m.id===id)).filter(Boolean) as Match[]}
  get openIssues(){return this.ops.issues.filter(i=>!i.resolved).length}
  time(s:string){return new Date(s).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}
  date(s:string){return new Date(s).toLocaleDateString([],{month:'short',day:'numeric'})}
  pair(m:Match,e:TournamentEvent){return m.players.map(id=>(e.entrants.find(p=>p.id===id)||{name:'TBD'}).name).join(' vs ')}
  playing(station:string):{event:TournamentEvent;match:Match}|undefined{for(const event of this.state.events){const match=event.matches.find(m=>m.station===station&&m.status==='playing');if(match)return {event,match}}}
  offline(station:string){return this.state.events.some(e=>e.operations&&e.operations.unavailable.includes(station))}
  remaining(s:string){const n=Math.max(0,Math.ceil((Date.parse(s)-this.now)/1000));return n?`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`:'Time elapsed'}
  send(action:string,data:any){return this.command('ops:'+action,data)}
  async addSession(){if(await this.send('sessionAdd',{...this.session,start:new Date(this.session.start).toISOString()}))this.session={title:'',start:'',minutes:60,owner:'',stations:[]}}
  async addIssue(){if(await this.send('issueAdd',this.issue))this.issue={title:'',owner:'',matchId:''}}
  printSheet(){window.print()}
  preparePrint(){this.clearPrint();const sheet=this.$el.querySelector('.print-sheet');if(sheet){const clone=sheet.cloneNode(true) as HTMLElement;clone.id='runback-print';document.body.appendChild(clone);document.body.classList.add('runback-printing')}}
  clearPrint(){const old=document.getElementById('runback-print');if(old)old.remove();document.body.classList.remove('runback-printing')}
  mounted(){window.addEventListener('beforeprint',this.preparePrint);window.addEventListener('afterprint',this.clearPrint);this.timer=setInterval(()=>this.now=Date.now(),1000)}
  beforeDestroy(){clearInterval(this.timer);window.removeEventListener('beforeprint',this.preparePrint);window.removeEventListener('afterprint',this.clearPrint);this.clearPrint()}
}
</script>
